<?php

declare(strict_types=1);

namespace App\Modules\Tenancy\Application;

use App\Modules\Identity\Application\TenantStaffAuthorizationService;
use App\Modules\Identity\Domain\TenantStaffContext;
use App\Modules\Tenancy\Domain\AuthorizationDeniedException;
use App\Modules\Tenancy\Domain\SalesConflictException;
use App\Modules\Tenancy\Domain\TenantAccessException;
use Illuminate\Database\ConnectionInterface;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;

/** W3 transactional deal service. Cross-tenant IDs are checked inside the tenant connection. */
final class DealService
{
    private const CONNECTION = 'pgsql_tenant_runtime';
    public function __construct(private readonly TenantStaffAuthorizationService $authorization) {}
    /** @return array{data:list<array<string,mixed>>,meta:array<string,int>} */
    public function list(TenantStaffContext $actor, ?string $stageId, int $page, int $perPage): array { $this->require($actor,'deals.view'); $q=DB::connection(self::CONNECTION)->table('deals')->where('tenant_id',$actor->tenantId); if($stageId!==null)$q->where('stage_id',$stageId); $total=(clone $q)->count(); return ['data'=>$q->orderByDesc('created_at')->forPage($page,$perPage)->get()->map(fn(object $d)=>$this->present($d))->all(),'meta'=>['page'=>$page,'per_page'=>$perPage,'total'=>$total]]; }
    /** @return array<string,mixed> */ public function show(TenantStaffContext $actor,string $id): array { $this->require($actor,'deals.view'); return $this->present($this->find($actor,$id,false)); }
    /** @param array<string,mixed> $input @return array<string,mixed> */
    public function create(TenantStaffContext $actor,array $input): array { $this->require($actor,'deals.manage'); $deal=SalesInput::deal($input); return DB::connection(self::CONNECTION)->transaction(function()use($actor,$deal):array{$db=DB::connection(self::CONNECTION); $this->assertReferences($db,$actor,$deal); $id=(string)Str::uuid7();$now=now('UTC');$db->table('deals')->insert(['id'=>$id,'tenant_id'=>$actor->tenantId,...$deal,'status'=>'OPEN','lost_reason'=>null,'closed_at'=>null,'version'=>1,'created_at'=>$now,'updated_at'=>$now]);$this->activity($db,$actor,$deal['customer_id'],$id,null,'deal.created');return $this->present($this->find($actor,$id,false));}); }
    /** @param array<string,mixed> $input @return array<string,mixed> */
    public function update(TenantStaffContext $actor,string $id,array $input):array { $this->require($actor,'deals.manage'); return DB::connection(self::CONNECTION)->transaction(function()use($actor,$id,$input):array{$db=DB::connection(self::CONNECTION);$row=$this->find($actor,$id,true);if($row->status!=='OPEN')throw new SalesConflictException('Closed deals cannot be edited.');$deal=SalesInput::deal([...$this->present($row),...$input]);if($deal['pipeline_id']!==$row->pipeline_id||$deal['stage_id']!==$row->stage_id)throw new SalesConflictException('Use the transition endpoint to change stages.');$this->assertReferences($db,$actor,$deal);$db->table('deals')->where('tenant_id',$actor->tenantId)->where('id',$id)->update([...$deal,'updated_at'=>now('UTC')]);$this->activity($db,$actor,$deal['customer_id'],$id,null,'deal.updated');return $this->present($this->find($actor,$id,false));}); }
    /** @param array<string,mixed> $input @return array<string,mixed> */
    public function transition(TenantStaffContext $actor,string $id,array $input): array { $this->require($actor,'deals.manage');$input=SalesInput::transition($input);return DB::connection(self::CONNECTION)->transaction(function()use($actor,$id,$input):array{$db=DB::connection(self::CONNECTION);$deal=$this->find($actor,$id,true);if($deal->status!=='OPEN'||$deal->stage_id!==$input['from_stage_id']||(int)$deal->version!==$input['version'])throw new SalesConflictException('Deal version or stage conflicts.');$stage=$db->table('sales_pipeline_stages')->where('tenant_id',$actor->tenantId)->where('pipeline_id',$deal->pipeline_id)->where('id',$input['to_stage_id'])->where('is_active',true)->first();if($stage===null)throw TenantAccessException::objectNotFound();$status=$stage->kind==='WON'?'WON':($stage->kind==='LOST'?'LOST':'OPEN');$now=now('UTC');$db->table('deals')->where('tenant_id',$actor->tenantId)->where('id',$id)->update(['stage_id'=>$stage->id,'status'=>$status,'closed_at'=>$status==='OPEN'?null:$now,'version'=>(int)$deal->version+1,'updated_at'=>$now]);$db->table('deal_stage_transitions')->insert(['id'=>(string)Str::uuid7(),'tenant_id'=>$actor->tenantId,'deal_id'=>$id,'from_stage_id'=>$deal->stage_id,'to_stage_id'=>$stage->id,'version'=>(int)$deal->version+1,'changed_by_membership_id'=>$actor->membershipId,'created_at'=>$now]);$this->activity($db,$actor,$deal->customer_id,$id,null,'deal.stage_changed');return $this->present($this->find($actor,$id,false));}); }
    private function assertReferences(ConnectionInterface $db,TenantStaffContext $actor,array $deal):void{$customer=$db->table('customers')->where('tenant_id',$actor->tenantId)->where('id',$deal['customer_id'])->first();if($customer===null)throw TenantAccessException::objectNotFound();if($deal['contact_id']!==null&&!$db->table('customer_contacts')->where('tenant_id',$actor->tenantId)->where('customer_id',$deal['customer_id'])->where('id',$deal['contact_id'])->exists())throw TenantAccessException::objectNotFound();if(!$db->table('sales_pipeline_stages')->where('tenant_id',$actor->tenantId)->where('pipeline_id',$deal['pipeline_id'])->where('id',$deal['stage_id'])->where('is_active',true)->exists())throw TenantAccessException::objectNotFound();if($deal['owner_membership_id']!==null&&!$db->table('tenant_staff_memberships')->where('tenant_id',$actor->tenantId)->where('id',$deal['owner_membership_id'])->where('status','ACTIVE')->exists())throw TenantAccessException::objectNotFound();}
    private function find(TenantStaffContext $actor,string $id,bool $lock):object{$q=DB::connection(self::CONNECTION)->table('deals')->where('tenant_id',$actor->tenantId)->where('id',$id);if($lock)$q->lockForUpdate();$row=$q->first();if($row===null)throw TenantAccessException::objectNotFound();return $row;}
    private function activity(ConnectionInterface $db,TenantStaffContext $actor,string $customerId,string $dealId,?string $taskId,string $event):void{$db->table('sales_activities')->insert(['id'=>(string)Str::uuid7(),'tenant_id'=>$actor->tenantId,'customer_id'=>$customerId,'deal_id'=>$dealId,'task_id'=>$taskId,'event_type'=>$event,'actor_membership_id'=>$actor->membershipId,'metadata'=>json_encode([],JSON_THROW_ON_ERROR),'occurred_at'=>now('UTC')]);}
    /** @return array<string,mixed> */ private function present(object $d):array{return ['id'=>$d->id,'customer_id'=>$d->customer_id,'contact_id'=>$d->contact_id,'pipeline_id'=>$d->pipeline_id,'stage_id'=>$d->stage_id,'title'=>$d->title,'value_amount'=>(string)$d->value_amount,'currency_code'=>$d->currency_code,'owner_membership_id'=>$d->owner_membership_id,'status'=>$d->status,'lost_reason'=>$d->lost_reason,'closed_at'=>$d->closed_at,'version'=>(int)$d->version,'created_at'=>$d->created_at,'updated_at'=>$d->updated_at];}
    private function require(TenantStaffContext $actor,string $permission):void{if(!in_array(null,$this->authorization->effectiveGrants($actor)[$permission]??[],true))throw new AuthorizationDeniedException;}
}
